#!/usr/bin/env node
// Generated files of the business-rules wiki (ADR-0030 decision 4). The pages of docs/wiki are
// written by hand; this script writes only what derives from them: the folder indexes
// (domain/Domain-model.md, rules/Business-rules.md, how-to/How-to.md, decisions/Decisions.md,
// api/API.md), _Sidebar.md, one API page per OpenAPI document of docs/api
// (api/Catalog-service-API.md) and graph.json (one node per page, one `link` edge per page link).
// Every Markdown file starts with the header `<!-- generated by scripts/gen-wiki.mjs | sources:
// <hash> | do not edit -->`, read by recordedHash() of scripts/lib/registry-sources.mjs, and
// graph.json carries `x-sources` (the ADR-0029 stamp). The hash covers the hand-written files, the
// OpenAPI documents without their own stamp and the files the pages name in `code` (graph.json
// holds their current hash); it has no date, so a second run writes the same bytes. wikiStatus()
// is the freshness and lint check scripts/check-docs-fresh.mjs runs.
// Run: npm run docs:wiki (alone) or npm run docs:registry (after the OpenAPI export).
import { createHash } from 'node:crypto';
import {
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  rmSync,
  statSync,
  writeFileSync,
} from 'node:fs';
import { dirname, join, posix, relative, resolve, sep } from 'node:path';
import { fileURLToPath } from 'node:url';
import { API_DIR } from './gen-api-docs.mjs';
import { isUnder } from './lib/hook-utils.mjs';
import { recordedHash } from './lib/registry-sources.mjs';
import {
  WIKI_GENERATED_MARK,
  parseFrontmatter,
  wikiFileName,
  wikiPageShapeErrors,
} from './lib/doc-shapes.mjs';

/** Folder of the wiki, relative to the project root. */
export const WIKI_DIR = 'docs/wiki';
/** The link graph, committed and stamped, read by scripts/wiki.mjs. */
export const GRAPH = `${WIKI_DIR}/graph.json`;
const HOME = `${WIKI_DIR}/Home.md`;
const SIDEBAR = `${WIKI_DIR}/_Sidebar.md`;
/** The generated index of each folder: file name, title and what the folder holds. */
export const WIKI_INDEXES = {
  domain: {
    file: 'Domain-model.md',
    title: 'Domain model',
    intro:
      'One page per entity of the catalog in plain language: what it is, the fields that matter and the rules that apply.',
  },
  rules: {
    file: 'Business-rules.md',
    title: 'Business rules',
    intro: 'One page per business rule, with its id, its status and the history of its changes.',
  },
  'how-to': {
    file: 'How-to.md',
    title: 'How-to',
    intro: 'What a user of the catalog does, step by step, and the rules each step meets.',
  },
  decisions: {
    file: 'Decisions.md',
    title: 'Decisions',
    intro: 'The decisions that shape the catalog in plain language, each linking its ADR.',
  },
  api: {
    file: 'API.md',
    title: 'API',
    intro: 'The OData API of the catalog, generated from the committed OpenAPI documents.',
  },
};
const OPENAPI_SUFFIX = '.openapi3.json';
const SKIP_DIRS = new Set(['node_modules', '.git', '.pipeline', 'dist', 'gen', 'coverage']);
const SWAGGER = 'http://localhost:4004/$api-docs';
const OPERATIONS = ['read', 'create', 'update', 'delete', 'draft'];
const DRAFT_ACTIONS = new Set(['draftActivate', 'draftEdit', 'draftPrepare']);
// The range of the language hook (CYRILLIC_SCOPE in scripts/lib/file-checks.mjs), built from code
// points so this file stays English.
const CYRILLIC = new RegExp(`[${String.fromCodePoint(0x400)}-${String.fromCodePoint(0x4ff)}]`);
// What follows the `](` of an inline link or image: the target, `<...>` or without spaces and `)`,
// an optional "title" and the closing `)`. Sticky: matched at the position after `](` only.
const DESTINATION = /(\s*)(<[^>]*>|[^)\s]+)((?:\s+"[^"]*")?\s*\))/y;
const REFERENCE = /^(\s{0,3}\[[^\]]+\]:\s*)(<[^>]*>|\S+)(.*)$/;

const posixRel = (root, file) => relative(root, file).split(sep).join('/');
const asList = (value) => (Array.isArray(value) ? value : value ? [value] : []);
const asText = (value) => (typeof value === 'string' && value ? value : null);
const byText = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
const cell = (text) =>
  String(text ?? '')
    .replace(/\|/g, '\\|')
    .replace(/\n/g, ' ');
const header = (hash) => `${WIKI_GENERATED_MARK} | sources: ${hash} | do not edit -->`;

function walk(dir, acc = []) {
  if (!existsSync(dir)) return acc;
  for (const name of readdirSync(dir)) {
    const full = join(dir, name);
    if (!statSync(full).isDirectory()) acc.push(full);
    else if (!SKIP_DIRS.has(name)) walk(full, acc);
  }
  return acc;
}

/**
 * Every Markdown file of docs/wiki with its kind: generated (starts with the generator header),
 * special (`_Footer.md`, `_Sidebar.md`), or a hand-written page (neither).
 * @param {string} root project root
 * @returns {Array<{path: string, text: string, generated: boolean, special: boolean}>} by path
 */
export function readWikiFiles(root) {
  return walk(join(root, WIKI_DIR))
    .filter((file) => file.endsWith('.md'))
    .map((file) => {
      const text = readFileSync(file, 'utf8');
      const path = posixRel(root, file);
      return {
        path,
        text,
        generated: text.startsWith(WIKI_GENERATED_MARK),
        special: posix.basename(path).startsWith('_'),
      };
    })
    .sort((a, b) => byText(a.path, b.path));
}

/**
 * The end (exclusive) of the backtick run at `at`: past the code span it opens when a run of the
 * same length closes it later on the line, else past the run itself, which is then plain text
 * (CommonMark code spans; a backslash inside a span escapes nothing).
 */
function backtickEnd(line, at) {
  let n = 0;
  while (line[at + n] === '`') n++;
  for (let j = at + n; j < line.length;) {
    let m = 0;
    while (line[j + m] === '`') m++;
    if (m === n) return j + m;
    j += m || 1;
  }
  return at + n;
}

/** The index of the `]` closing the `[` at `open`, over nested brackets, code spans and escapes. */
function closingBracket(line, open) {
  let depth = 0;
  for (let j = open; j < line.length; j++) {
    const c = line[j];
    if (c === '\\') j++;
    else if (c === '`') j = backtickEnd(line, j) - 1;
    else if (c === '[') depth++;
    else if (c === ']' && --depth === 0) return j;
  }
  return -1;
}

/**
 * Applies `visit(target, image)` to the target of each inline link and image of a line, left to
 * right: a code span outside a link text is copied as it is, a link text may hold code spans,
 * brackets and images (visited before the target of the link around them), a backslash-escaped
 * `[` opens none. `image` is true for the target of `![...](...)`.
 */
function mapInline(line, visit) {
  let out = '';
  let i = 0;
  while (i < line.length) {
    const c = line[i];
    if (c === '\\' || c === '`') {
      const end = c === '\\' ? i + 2 : backtickEnd(line, i);
      out += line.slice(i, end);
      i = end;
      continue;
    }
    const open = c === '[' ? i : c === '!' && line[i + 1] === '[' ? i + 1 : -1;
    const close = open < 0 ? -1 : closingBracket(line, open);
    DESTINATION.lastIndex = close + 2;
    const dest = close >= 0 && line[close + 1] === '(' ? DESTINATION.exec(line) : null;
    if (!dest) {
      out += c;
      i++;
      continue;
    }
    const [all, ws, target, rest] = dest;
    const text = mapInline(line.slice(open + 1, close), visit);
    out += `${line.slice(i, open + 1)}${text}](${ws}${visit(target, c === '!')}${rest}`;
    i = close + 2 + all.length;
  }
  return out;
}

/**
 * Calls `visit(target, image)` for each link of a line: a reference definition, which counts as a
 * link (ADR-0030 amendment A), or the inline links and images.
 */
function mapLinks(line, visit) {
  const ref = line.match(REFERENCE);
  if (ref) return `${ref[1]}${visit(ref[2], false)}${ref[3]}`;
  return mapInline(line, visit);
}

/** Applies `visit` to the lines of a Markdown text outside fenced code blocks. */
function mapLines(text, visit) {
  let fence = null;
  return String(text)
    .split('\n')
    .map((line, i) => {
      const f = line.match(/^\s*(`{3,}|~{3,})/);
      if (f) fence = !fence ? f[1][0] : f[1][0] === fence ? null : fence;
      return f || fence ? line : visit(line, i);
    })
    .join('\n');
}

/**
 * Rewrites the link targets of a Markdown text: inline links, images and reference definitions,
 * outside code spans and fenced blocks; a link whose text holds a code span counts like any other.
 * The one link reader of the wiki tooling: wikiStatus(), the graph edges and the export use it.
 * @param {string} text Markdown
 * @param {function(string, number, boolean): string} visit gets a target as written (`<...>`
 *   included), its 0-based line index and whether it is the target of an image (`![...](...)`;
 *   false for a reference definition), returns the target to write
 * @returns {string} the text with the returned targets
 */
export function mapLinkTargets(text, visit) {
  return mapLines(text, (line, i) => mapLinks(line, (target, image) => visit(target, i, image)));
}

/**
 * The links of a Markdown text, read by mapLinkTargets().
 * @param {string} text Markdown
 * @param {number} [firstLine] line number of the first line of `text` in its file
 * @returns {Array<{target: string, line: number}>} the targets without `<>`, with line numbers
 */
export function markdownLinks(text, firstLine = 1) {
  const out = [];
  mapLinkTargets(text, (target, i) => {
    out.push({ target: target.replace(/^<|>$/g, ''), line: firstLine + i });
    return target;
  });
  return out;
}

/**
 * Where a link of a wiki file points.
 * @param {string} fromPath repository path of the file holding the link
 * @param {string} target the link target as written
 * @returns {{kind: 'external'|'anchor'|'wiki'|'repo', path?: string, anchor?: string}} `wiki` for a
 *   target inside docs/wiki, `repo` for any other repository path (may start with `../` when it
 *   leaves the repository)
 */
export function resolveLink(fromPath, target) {
  if (/^[a-z][a-z0-9+.-]*:/i.test(target) || target.startsWith('//')) return { kind: 'external' };
  if (target.startsWith('#')) return { kind: 'anchor' };
  const [file, ...rest] = target.split('#');
  let decoded = file.split('?')[0];
  try {
    decoded = decodeURI(decoded);
  } catch {
    // keep the raw target; the existence check reports it
  }
  const path = decoded.startsWith('/')
    ? posix.normalize(decoded.slice(1))
    : posix.normalize(posix.join(posix.dirname(fromPath), decoded));
  const anchor = rest.length ? `#${rest.join('#')}` : '';
  return { kind: path.startsWith(`${WIKI_DIR}/`) ? 'wiki' : 'repo', path, anchor };
}

/**
 * The repository files a page's `code` entries name: paths or globs of isUnder() in
 * scripts/lib/hook-utils.mjs, walked from the part before the first wildcard only.
 * @param {string} root project root
 * @param {Array<string>} globs the `code` entries
 * @returns {Array<string>} repository paths, sorted, without duplicates
 */
export function codeFiles(root, globs) {
  const found = new Set();
  for (const glob of globs) {
    const segments = glob.split('/');
    const wild = segments.findIndex((s) => /[*?{]/.test(s));
    const base = (wild < 0 ? segments : segments.slice(0, wild)).join('/');
    const abs = join(root, base);
    if (!base || !existsSync(abs)) continue;
    const candidates = statSync(abs).isDirectory()
      ? walk(abs).map((file) => posixRel(root, file))
      : [base];
    for (const file of candidates) if (isUnder(file, glob)) found.add(file);
  }
  return [...found].sort(byText);
}

function updateWithFiles(hash, root, files) {
  for (const file of files) {
    hash.update(file);
    hash.update('\n');
    hash.update(readFileSync(join(root, file)));
    hash.update('\n');
  }
}

/**
 * The hash a page's `verified` stamp records: sha256 over the paths and contents of its code
 * files, 16 hex characters, the algorithm of sourcesHash() in scripts/lib/registry-sources.mjs.
 * @param {string} root project root
 * @param {Array<string>} globs the page's `code` entries
 * @returns {string} the hash
 */
export function codeHash(root, globs) {
  const hash = createHash('sha256');
  updateWithFiles(hash, root, codeFiles(root, globs));
  return hash.digest('hex').slice(0, 16);
}

function openApiDocuments(root) {
  const dir = join(root, API_DIR);
  return existsSync(dir)
    ? readdirSync(dir)
        .filter((name) => name.endsWith(OPENAPI_SUFFIX))
        .sort(byText)
        .map((name) => `${API_DIR}/${name}`)
    : [];
}

/**
 * The sources hash of the generated wiki files: the hand-written files of docs/wiki, the OpenAPI
 * documents without `info['x-sources']` (that stamp changes with every registry source) and the
 * files the pages name in `code`.
 * @param {string} root project root
 * @returns {string} 16 hex characters
 */
export function wikiSourcesHash(root) {
  const hash = createHash('sha256');
  const written = readWikiFiles(root).filter((f) => !f.generated);
  for (const f of written) {
    hash.update(f.path);
    hash.update('\n');
    hash.update(f.text);
    hash.update('\n');
  }
  for (const doc of openApiDocuments(root)) {
    let text = readFileSync(join(root, doc), 'utf8');
    try {
      const json = JSON.parse(text);
      if (json.info) delete json.info['x-sources'];
      text = JSON.stringify(json);
    } catch {
      // an unreadable document is hashed as it is
    }
    hash.update(doc);
    hash.update('\n');
    hash.update(text);
    hash.update('\n');
  }
  const globs = written.flatMap((f) => asList(parseFrontmatter(f.text).meta?.code));
  updateWithFiles(hash, root, codeFiles(root, globs));
  return hash.digest('hex').slice(0, 16);
}

/**
 * The hand-written pages of docs/wiki (no generated file, no `_*.md`), parsed.
 * @param {string} root project root
 * @returns {Array<{path: string, folder: string, meta: object, text: string, links: Array<object>,
 *   codeHash: string|null}>} by path; `folder` is '' for docs/wiki itself, `links` carry the
 *   resolveLink() result and the line, `codeHash` is null without `code`
 */
export function readPages(root) {
  return readWikiFiles(root)
    .filter((f) => !f.generated && !f.special)
    .map((f) => {
      const { meta, body, bodyLine } = parseFrontmatter(f.text);
      const inner = f.path.slice(WIKI_DIR.length + 1);
      const code = asList(meta?.code);
      return {
        path: f.path,
        folder: inner.includes('/') ? inner.split('/')[0] : '',
        meta: meta || {},
        text: f.text,
        links: markdownLinks(body, bodyLine + 1).map((l) => ({
          ...l,
          ...resolveLink(f.path, l.target),
        })),
        codeHash: code.length ? codeHash(root, code) : null,
      };
    });
}

/**
 * The link graph of the pages (ADR-0030 decision 4): one node per page with its frontmatter and
 * the current hash of its code files, one `link` edge per page that links another page. Links to
 * generated files and to the repository are no edges.
 * @param {Array<object>} pages the result of readPages()
 * @returns {{nodes: Array<object>, edges: Array<{from: string, to: string, type: string}>}} graph
 */
export function buildGraph(pages) {
  const known = new Set(pages.map((p) => p.path));
  const nodes = pages.map(({ path, folder, meta, codeHash: current }) => ({
    path,
    folder,
    id: asText(meta.id),
    title: asText(meta.title),
    summary: asText(meta.summary),
    tags: asList(meta.tags),
    code: asList(meta.code),
    messages: asList(meta.messages),
    elements: asList(meta.elements),
    status: asText(meta.status),
    sources: asList(meta.sources),
    verified: asText(meta.verified),
    codeHash: current,
    aliases: asList(meta.aliases),
    adr: asList(meta.adr),
  }));
  const edges = [];
  const seen = new Set();
  for (const page of pages) {
    for (const link of page.links) {
      const key = `${page.path} ${link.path}`;
      if (link.kind !== 'wiki' || link.path === page.path || !known.has(link.path)) continue;
      if (seen.has(key)) continue;
      seen.add(key);
      edges.push({ from: page.path, to: link.path, type: 'link' });
    }
  }
  return { nodes, edges };
}

const titleOf = (page) => asText(page.meta.title) || posix.basename(page.path, '.md');
const linkFrom = (from, to, text) => `[${cell(text)}](${posix.relative(posix.dirname(from), to)})`;
const byTitle = (a, b) => byText(titleOf(a).toLowerCase(), titleOf(b).toLowerCase());

/** `CatalogService` as words in sentence case: `Catalog service`. */
const sentence = (name) => {
  const [first, ...rest] = name.replace(/([a-z0-9])([A-Z])/g, '$1 $2').split(' ');
  return [first, ...rest.map((w) => w.toLowerCase())].join(' ');
};

function apiPageOf(doc) {
  const service = posix.basename(doc, OPENAPI_SUFFIX);
  const title = `${sentence(service)} API`;
  return { doc, title, path: `${WIKI_DIR}/api/${wikiFileName(title)}.md` };
}

function indexLines(folder, at, own, apiPages) {
  if (folder === 'rules') {
    const rows = [...own]
      .sort((a, b) => byText(asText(a.meta.id) || '', asText(b.meta.id) || ''))
      .map(
        (p) =>
          `| ${cell(p.meta.id)} | ${linkFrom(at, p.path, titleOf(p))} | ${cell(p.meta.status)} | ${cell(p.meta.summary)} |`
      );
    return rows.length ? ['| Id | Rule | Status | Summary |', '|---|---|---|---|', ...rows] : [];
  }
  // Decisions: digests by ADR number, list pages (several ADRs) after them; other folders by title.
  const adrKey = (p) => (asList(p.meta.adr).length > 1 ? 'list' : asList(p.meta.adr)[0] || '');
  const order = folder === 'decisions' ? (a, b) => byText(adrKey(a), adrKey(b)) : () => 0;
  const items = [...own].sort((a, b) => order(a, b) || byTitle(a, b));
  const lines = items.map((p) => {
    const adr = asList(p.meta.adr);
    const note =
      folder !== 'decisions' ? '' : adr.length > 1 ? ` (${adr.length} ADRs)` : ` (${adr[0]})`;
    return `- ${linkFrom(at, p.path, titleOf(p))}${note}: ${p.meta.summary ?? ''}`;
  });
  if (folder !== 'api') return lines;
  const generated = apiPages.map(
    (a) => `- ${linkFrom(at, a.path, a.title)}: ${a.json.info?.description ?? ''}`
  );
  return [...generated, ...lines];
}

function renderIndex(folder, pages, apiPages, hash) {
  const { file, title, intro } = WIKI_INDEXES[folder];
  const at = `${WIKI_DIR}/${folder}/${file}`;
  const lines = indexLines(
    folder,
    at,
    pages.filter((p) => p.folder === folder),
    apiPages
  );
  return [
    header(hash),
    `# ${title}`,
    '',
    `${intro} This list is generated from the pages of the folder; edit the pages, never this file.`,
    '',
    ...(lines.length ? lines : ['_No pages yet._']),
    '',
  ].join('\n');
}

function renderSidebar(pages, hash) {
  const top = pages.filter((p) => p.folder === '' && p.path !== HOME).sort(byTitle);
  return [
    header(hash),
    `**${linkFrom(SIDEBAR, HOME, 'Home')}**`,
    '',
    ...Object.entries(WIKI_INDEXES).map(
      ([folder, { file, title }]) =>
        `- ${linkFrom(SIDEBAR, `${WIKI_DIR}/${folder}/${file}`, title)}`
    ),
    ...top.map((p) => `- ${linkFrom(SIDEBAR, p.path, titleOf(p))}`),
    '',
  ].join('\n');
}

function entitySets(json) {
  const sets = new Map();
  const actions = [];
  const set = (name) => {
    if (!sets.has(name)) sets.set(name, { name, ops: new Set(), tag: null });
    return sets.get(name);
  };
  for (const [path, item] of Object.entries(json.paths || {})) {
    const methods = Object.keys(item).filter((m) => m !== 'parameters');
    const collection = path.match(/^\/(\w+)$/);
    const single = path.match(/^\/(\w+)\([^/]*\)$/);
    const bound = path.match(/^\/(\w+)(?:\([^/]*\))?\/\w+\.(\w+)$/);
    if (collection && methods.includes('get')) {
      const s = set(collection[1]);
      s.tag = item.get.tags?.[0] ?? null;
      s.ops.add('read');
      if (methods.includes('post')) s.ops.add('create');
    } else if (collection) {
      actions.push({ name: collection[1], boundTo: '', summary: item.post?.summary ?? '' });
    } else if (single) {
      const s = set(single[1]);
      if (methods.includes('get')) s.ops.add('read');
      if (methods.includes('patch') || methods.includes('put')) s.ops.add('update');
      if (methods.includes('delete')) s.ops.add('delete');
    } else if (bound && DRAFT_ACTIONS.has(bound[2])) {
      if (bound[2] === 'draftEdit') set(bound[1]).ops.add('draft');
    } else if (bound) {
      const op = item.post ?? item.get ?? {};
      actions.push({ name: bound[2], boundTo: bound[1], summary: op.summary ?? '' });
    }
  }
  return { sets: [...sets.values()].sort((a, b) => byText(a.name, b.name)), actions };
}

function renderApiPage(api, pages, hash) {
  const { json, title, path: at, doc } = api;
  const tags = new Map((json.tags || []).map((t) => [t.name, t.description ?? '']));
  const domain = new Map(
    pages
      .filter((p) => p.folder === 'domain')
      .map((p) => [posix.basename(p.path, '.md').toLowerCase(), p])
  );
  const { sets, actions } = entitySets(json);
  const server = json.servers?.[0]?.url ?? '';
  const schemes = Object.entries(json.components?.securitySchemes || {});
  const auth = schemes.length
    ? schemes
        .map(([name, s]) => `\`${name}\` (${s.type}${s.scheme ? ` ${s.scheme}` : ''})`)
        .join(', ')
    : `the OpenAPI document declares no security scheme; the roles and restrictions of the service are in ${linkFrom(at, 'docs/registry/SERVICES.md', 'SERVICES.md')}`;
  const rows = sets.map((s) => {
    const page = domain.get(wikiFileName(sentence(s.name)).toLowerCase());
    const ops = OPERATIONS.filter((op) => s.ops.has(op)).join(', ');
    const description = s.tag ? tags.get(s.tag) : '';
    return `| ${s.name} | ${cell(description)} | ${ops} | ${page ? linkFrom(at, page.path, titleOf(page)) : ''} |`;
  });
  const actionRows = actions.map(
    (a) => `| ${a.name} | ${a.boundTo || 'service'} | ${cell(a.summary)} |`
  );
  return [
    header(hash),
    `# ${title}`,
    '',
    ...(json.info?.description ? [json.info.description, ''] : []),
    `Generated from the committed OpenAPI document ${linkFrom(at, doc, posix.basename(doc))} (\`npm run docs:registry\`); the elements of each entity with their types are in ${linkFrom(at, 'docs/registry/DOMAIN-MODEL.md', 'DOMAIN-MODEL.md')}. A description here is a doc comment in \`db/\` or \`srv/\`: change it there and regenerate.`,
    '',
    '## Access',
    '',
    `- Service root: \`${server}\`${json['x-odata-version'] ? ` (OData ${json['x-odata-version']})` : ''}.`,
    `- Authentication: ${auth}.`,
    `- Swagger UI while \`npm run watch\` runs (development only): <${SWAGGER}${server}>.`,
    '',
    '## Entity sets',
    '',
    '| Entity set | What it holds | Operations | Domain page |',
    '|---|---|---|---|',
    ...rows,
    '',
    '## Actions',
    '',
    ...(actionRows.length
      ? ['| Action | Bound to | What it does |', '|---|---|---|', ...actionRows]
      : ['_None._']),
    '',
  ].join('\n');
}

/**
 * Renders every generated file of the wiki from the current pages and OpenAPI documents.
 * @param {string} root project root
 * @returns {{hash: string, files: Map<string, string>}} the sources hash and the content per
 *   repository path
 */
export function renderWiki(root) {
  const hash = wikiSourcesHash(root);
  const pages = readPages(root);
  const apiPages = openApiDocuments(root).map((doc) => ({
    ...apiPageOf(doc),
    json: JSON.parse(readFileSync(join(root, doc), 'utf8')),
  }));
  const files = new Map();
  for (const [folder, { file }] of Object.entries(WIKI_INDEXES)) {
    files.set(`${WIKI_DIR}/${folder}/${file}`, renderIndex(folder, pages, apiPages, hash));
  }
  for (const api of apiPages) files.set(api.path, renderApiPage(api, pages, hash));
  files.set(SIDEBAR, renderSidebar(pages, hash));
  const graph = { 'x-sources': hash, ...buildGraph(pages) };
  files.set(GRAPH, JSON.stringify(graph, null, 2) + '\n');
  return { hash, files };
}

/**
 * Writes the generated files of docs/wiki and removes a generated file no longer produced (the
 * API page of a removed service). Nothing happens when docs/wiki does not exist.
 * @param {string} root project root
 * @returns {Array<string>} the generated files, repository paths
 */
export function writeWiki(root) {
  if (!existsSync(join(root, WIKI_DIR))) return [];
  const { files } = renderWiki(root);
  for (const [path, content] of files) {
    const abs = join(root, path);
    if (existsSync(abs) && readFileSync(abs, 'utf8') === content) continue;
    mkdirSync(dirname(abs), { recursive: true });
    writeFileSync(abs, content);
  }
  for (const f of readWikiFiles(root)) {
    if (f.generated && !files.has(f.path)) rmSync(join(root, f.path));
  }
  return [...files.keys()];
}

function graphRecordedHash(file) {
  try {
    const stamp = JSON.parse(readFileSync(file, 'utf8'))['x-sources'];
    return typeof stamp === 'string' && /^[0-9a-f]{16}$/.test(stamp) ? stamp : null;
  } catch {
    return null;
  }
}

function brokenLinks(root, files) {
  const reasons = [];
  for (const f of files) {
    const { body, bodyLine } = parseFrontmatter(f.text);
    const seen = new Set();
    for (const { target, line } of markdownLinks(body, bodyLine + 1)) {
      const link = resolveLink(f.path, target);
      if (link.kind === 'external' || link.kind === 'anchor' || seen.has(target)) continue;
      seen.add(target);
      if (link.path.startsWith('..') || !existsSync(join(root, link.path)))
        reasons.push(`${f.path}:${line}: broken link ${target}`);
    }
  }
  return reasons;
}

function groupedBy(items, key) {
  const groups = new Map();
  for (const item of items) {
    const k = key(item);
    if (k) groups.set(k, [...(groups.get(k) || []), item.path]);
  }
  return [...groups].filter(([, paths]) => paths.length > 1);
}

function wikiLint(root, files) {
  const pages = readPages(root);
  const written = files.filter((f) => !f.generated);
  const reasons = [];
  for (const p of pages)
    for (const e of wikiPageShapeErrors(p.text, p.path)) reasons.push(`${p.path}: ${e}`);
  for (const [id, paths] of groupedBy(pages, (p) => asText(p.meta.id)))
    reasons.push(`${paths.join(', ')}: rule id ${id} is used more than once`);
  reasons.push(...brokenLinks(root, written));
  for (const p of pages) {
    for (const s of asList(p.meta.sources)) {
      if (!/^[a-z][a-z0-9+.-]*:/i.test(s) && !existsSync(join(root, s)))
        reasons.push(`${p.path}: sources entry ${s} does not exist`);
    }
  }
  const linked = new Set(
    pages.flatMap((p) =>
      p.links.filter((l) => l.kind === 'wiki' && l.path !== p.path).map((l) => l.path)
    )
  );
  for (const p of pages) {
    if (p.path !== HOME && !linked.has(p.path))
      reasons.push(
        `${p.path}: orphan, no other page links to it (indexes and the sidebar do not count)`
      );
  }
  for (const [name, paths] of groupedBy(files, (f) => posix.basename(f.path).toLowerCase()))
    reasons.push(
      `${paths.join(', ')}: basename ${name} is used more than once; the GitHub Wiki serves pages flat by name`
    );
  for (const f of written) {
    const hits = f.text
      .split('\n')
      .map((line, i) => (CYRILLIC.test(line) ? i + 1 : 0))
      .filter(Boolean);
    if (hits.length)
      reasons.push(
        `${f.path}: Cyrillic on line(s) ${hits.join(', ')}; the wiki is English (ADR-0030)`
      );
  }
  return reasons;
}

/**
 * Freshness and lint of docs/wiki for scripts/check-docs-fresh.mjs (ADR-0030 decision 4): a
 * generated file that is missing, unstamped, stale or no longer produced (`--fix` regenerates
 * them), and the findings a generator cannot fix: page shape errors, a rule id used twice, broken
 * relative links, missing `sources` paths, orphan pages, a basename used twice, Cyrillic.
 * @param {string} root project root
 * @returns {Array<string>} one reason per finding; empty when the wiki is fresh and clean, and when
 *   the project has no docs/wiki
 */
export function wikiStatus(root) {
  if (!existsSync(join(root, WIKI_DIR))) return [];
  const { hash, files: expected } = renderWiki(root);
  const reasons = [];
  for (const path of expected.keys()) {
    const abs = join(root, path);
    const recorded = path === GRAPH ? graphRecordedHash(abs) : recordedHash(abs);
    if (!existsSync(abs)) reasons.push(`${path}: missing; run npm run docs:wiki`);
    else if (!recorded)
      reasons.push(`${path}: no generator stamp (${path === GRAPH ? 'x-sources' : 'header'})`);
    else if (recorded !== hash)
      reasons.push(`${path}: sources ${recorded} does not match the current wiki sources ${hash}`);
  }
  const files = readWikiFiles(root);
  for (const f of files) {
    if (f.generated && !expected.has(f.path))
      reasons.push(`${f.path}: a generated file the generator no longer writes`);
  }
  return [...reasons, ...wikiLint(root, files)];
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const root = process.cwd();
  const files = writeWiki(root);
  if (!files.length) console.log(`${WIKI_DIR} does not exist; nothing to generate.`);
  else
    console.log(`${WIKI_DIR}: ${files.length} generated files (sources ${wikiSourcesHash(root)}).`);
}
